"use client"

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { Slot, Toggle as TogglePrimitive } from "radix-ui"

import { useInk, useMergedRef } from "@/lib/ink/react"
import { toggleRecipe, type ToggleTone } from "@/lib/ink/recipes/toggle-ink"
import { cn } from "@/lib/utils"

const toggleVariants = cva(
  "relative isolate inline-flex shrink-0 items-center justify-center gap-2 font-hand font-bold whitespace-nowrap transition-[translate] duration-(--ll-dur-press) ease-out active:translate-y-(--ll-press-sink) [&[data-pressed]:not([data-pressed=false])]:translate-y-(--ll-press-sink) disabled:pointer-events-none disabled:text-pencil-text forced-colors:data-[state=on]:bg-[Highlight] forced-colors:data-[state=on]:text-[HighlightText] [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not(.absolute):not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "",
        outline: "",
      },
      size: {
        default: "h-9 min-w-9 px-2 text-base compact:h-8 compact:min-w-8 calm:h-7 calm:min-w-7",
        sm: "h-8 min-w-8 px-1.5 text-[15px] compact:h-7 compact:min-w-7 calm:h-7 calm:min-w-7",
        lg: "h-10 min-w-10 px-2.5 text-[17px] compact:h-9 compact:min-w-9 calm:h-8 calm:min-w-8",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Toggle({
  className,
  variant,
  size,
  tone,
  seed,
  asChild,
  disabled,
  children,
  ref,
  ...props
}: React.ComponentProps<typeof TogglePrimitive.Root> &
  VariantProps<typeof toggleVariants> & {
    tone?: ToggleTone
    seed?: string | number
  }) {
  const v = variant ?? "default"
  const forced = "data-focus-visible" in props
  const { hostRef, hostProps, node } = useInk({
    recipe: toggleRecipe,
    params: { variant: v, disabled: !!disabled, tone, invalid: props["aria-invalid"] === true || props["aria-invalid"] === "true" },
    kind: "toggle",
    seed,
    layers: forced ? "all" : undefined,
  })
  return (
    <TogglePrimitive.Root
      data-slot="toggle"
      data-variant={v}
      data-size={size ?? "default"}
      data-ink-sink="self"
      ref={useMergedRef<HTMLButtonElement>(hostRef, ref)}
      {...hostProps}
      asChild={asChild}
      disabled={disabled}
      className={cn(toggleVariants({ variant: v, size, className }))}
      {...props}
    >
      {!asChild && node}
      {asChild ? <Slot.Slottable>{children}</Slot.Slottable> : children}
      {asChild && node}
    </TogglePrimitive.Root>
  )
}

export { Toggle, toggleVariants }

import { bandFill, blobFill, wash } from '@/lib/ink/fills'
import { roundRectPoly, seg } from '@/lib/ink/geom'
import { clamp } from '@/lib/ink/rng'
import { box, chain, dashedBox, focusRing } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'

export const toggleVariantList = ['default', 'outline'] as const
export const toggleToneList = ['hi', 'marker'] as const
export type ToggleVariant = (typeof toggleVariantList)[number]
export type ToggleTone = (typeof toggleToneList)[number]

export interface ToggleParams {
  variant: ToggleVariant
  disabled?: boolean
  tone?: ToggleTone
  joined?: boolean
  vertical?: boolean
  invalid?: boolean
}

export const toggleRecipe = defineRecipe<ToggleParams>({
  id: 'toggle',
  kind: 'toggle',
  layers: ['rest', 'hover', 'checked', 'focus'],
  lazy: ['focus'],
  pad: 12,
  draw(ink, { w, h }, { variant, disabled, tone = 'hi', joined, vertical, invalid: invalidParam }, ctx) {
    const invalid = !!invalidParam && !disabled && !joined
    const r = clamp(Math.min(w, h) * 0.09, 2.2, 4.4)
    const inset = joined ? 0.9 : 0.5
    const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, joined ? 2 : r)
    const fillOpts = { ends: 'square' as const, W: clamp(Math.min(w, h) * 0.3, 5, 9), angle: w / h < 1.6 ? -0.04 : -0.02 }
    const small = Math.min(w, h) < 28
    const rtl = ctx.dir === 'rtl'
    const calm = ctx.calm

    if (!disabled) ctx.lazy('focus', (fink) => focusRing(fink, 0, 0, w, h, { r }))
    if (ctx.lazyOnly) return

    const wide = w > 360
    const disabledBox = () => dashedBox(ink, 0, 0, w, h, { r, pen: 'pencil', opts: { color: 'pencil', width: 1.2 } })
    const inkBox = (o: { inset?: number; alpha?: number; whisper?: boolean } = {}) => {
      const i = o.inset ?? 0
      const fine = calm || o.whisper
      const pen = invalid ? (fine ? 'red.fine' : 'red') : fine ? 'pencil.fine' : 'ink'
      const alpha = invalid ? undefined : o.alpha
      box(ink, i, i, w - 2 * i, h - 2 * i, {
        pen,
        corner: r,
        ...(fine ? { style: 'loop' as const, stubs: false, ghost: false } : {}),
        ...(alpha !== undefined || wide || calm || invalid
          ? { opts: { alpha, simple: wide || (calm && i > 0) || undefined, ...(invalid ? { width: 1.2 } : {}) } }
          : {}),
      })
    }

    ink.layer('rest', () => {
      if (joined) {
        ink.part(
          'seam',
          () => {
            const pen = disabled || variant === 'default' || calm ? 'pencil.fine' : 'ink.fine'
            const o = { start: 'soft' as const, end: 'flick' as const, alpha: disabled ? 0.55 : variant === 'default' ? 0.42 : 1 }
            if (vertical) ink.lines([{ pts: seg(w * 0.06, 0.2, w * 0.94, 0.6, 0.4, 5), o }], pen)
            else {
              const x = rtl ? w - 0.4 : 0.4
              ink.lines([{ pts: seg(x, h * 0.05, x + (rtl ? -0.5 : 0.5), h * 0.95, 0.5, 5), o }], pen)
            }
            return { dx: 0, dy: 0 }
          },
          'top'
        )
        return
      }
      if (disabled) {
        if (variant === 'outline') wash(ink, body, 'pencil-mark', { alpha: 0.12, material: 'wash' })
        disabledBox()
      } else if (variant === 'outline') inkBox()
      else inkBox({ inset: 0.6, alpha: 0.4, whisper: true })
    })

    if (!disabled) {
      ink.layer('hover', () => {
        if (variant === 'default' && !joined) inkBox({ inset: 0.6, alpha: 0.6, whisper: true })
        else wash(ink, body, 'hi', { alpha: joined || variant === 'default' ? 0.34 : 0.5 })
        if (calm && !joined) {
          box(ink, 1, 1, w - 2, h - 2, {
            pen: 'pencil.fine',
            corner: r,
            style: 'loop',
            stubs: false,
            ghost: false,
            loose: 0.6,
            opts: { alpha: 0.7, simple: true },
          })
          return
        }
        if (calm || joined || variant === 'default') return
        const d = 3.4 + h / 40
        ink.lines(
          [
            { pts: chain([[r + d + 2, h + d], [w + d, h + d], [w + d, r + d + 2]], [0.25, -0.2], Math.max(2.5, r + 1), ink.next('drop')), o: { start: 'soft', end: 'soft', wobble: 0.25, dry: 0 } },
          ],
          'ink.fine',
          { width: 1.3 }
        )
      })
    }

    ink.layer('checked', () => {
      if (disabled) {
        wash(ink, body, 'pencil-mark', { alpha: 0.35, material: 'wash' })
        return
      }
      const alpha = tone === 'marker' ? 0.86 : 0.82
      const mis = joined ? 1.3 : clamp(h * 0.06, 1.6, 3)
      ink.part('fill', () =>
        small ? blobFill(ink, body, tone, { alpha, mis }) : bandFill(ink, body, tone, { alpha, mis, passes: tone === 'marker' && !calm ? 2 : 1, ...fillOpts })
      )
      if (invalid) {
        box(ink, 0, 0, w, h, { pen: calm ? 'red.fine' : 'red', corner: r, ghost: false, ...(calm ? { style: 'loop' as const, stubs: false } : {}), opts: { width: 1.3, simple: wide || undefined } })
        return
      }
      if (variant === 'default' && !joined) {
        if (calm) box(ink, 0, 0, w, h, { pen: 'pencil.fine', corner: r, style: 'loop', stubs: false, ghost: false, opts: { simple: wide || undefined } })
        else box(ink, 0, 0, w, h, { pen: 'ink.fine', corner: r, ghost: false, opts: wide ? { simple: true } : undefined })
      }
    })
  },
})
